import { For } from 'solid-js';
import { LANGS, langName } from '../../model/i18n.js';
import { type Lang, text, view, setView } from '../../stores/view.js';
import { holdAnchor } from '../list/scroll-anchor.js';

export function LanguagePicker() {
  const langs = LANGS as Lang[];
  return (
    <select
      class="lang-select"
      id="language-picker"
      aria-label={text('lang.aria')}
      value={view.lang}
      onChange={(e) => {
        const chosen = e.currentTarget.value as Lang;
        if (chosen === view.lang) return;
        holdAnchor();
        setView({ lang: chosen });
      }}
    >
      <For each={langs}>{(l) => (
        <option value={l} selected={l === view.lang}>{langName(l)}</option>
      )}</For>
    </select>
  );
}
