import { createMemo, createSignal, For, Show } from 'solid-js';
import { prefGet, prefSet } from '../../model/prefs.js';

export interface NavNode {
  id: string;
  label: string;
  kind?: string;
  badge?: string | null;
  children?: NavNode[];
}

export interface NavRow {
  id: string;
  label: string;
  kind: string;
  badge: string | null;
  depth: number;
  parentId: string | null;
  hasChildren: boolean;
}

export function navRows(
  nav: NavNode[] | null | undefined,
  depth = 0,
  parentId: string | null = null,
  out: NavRow[] = [],
): NavRow[] {
  for (const node of nav || []) {
    const children = node.children || [];
    out.push({
      id: node.id, label: node.label, kind: node.kind || '',
      badge: node.badge || null, depth, parentId,
      hasChildren: children.length > 0,
    });
    navRows(children, depth + 1, node.id, out);
  }
  return out;
}

export function visibleRows(rows: NavRow[], closed: ReadonlySet<string>): NavRow[] {
  const hidden = new Set<string>();
  const visible: NavRow[] = [];
  for (const r of rows) {
    if (r.parentId !== null && (closed.has(r.parentId) || hidden.has(r.parentId))) {
      hidden.add(r.id);
      continue;
    }
    visible.push(r);
  }
  return visible;
}

const NONE_CLOSED: ReadonlySet<string> = new Set<string>();

export interface TreeProps {

  nav: NavNode[];

  onSelect: (id: string) => void;

  selected?: string | null;

  ignoreClosed?: boolean;
}

export function Tree(props: TreeProps) {
  const stored = prefGet('tree.closed', []);
  const [closed, setClosed] = createSignal<ReadonlySet<string>>(
    new Set<string>(Array.isArray(stored) ? (stored as string[]) : []));
  const rows = createMemo(() => navRows(props.nav));
  const visible = createMemo(() => visibleRows(
    rows(), props.ignoreClosed ? NONE_CLOSED : closed()));

  let body!: HTMLDivElement;

  const isClosed = (id: string) => !props.ignoreClosed && closed().has(id);

  function toggle(id: string) {
    const next = new Set(closed());
    if (next.has(id)) next.delete(id); else next.add(id);
    setClosed(next);
    prefSet('tree.closed', [...next]);

    const row = [...body.children].find(
      (n) => n.getAttribute && n.getAttribute('data-id') === id) as HTMLElement | undefined;
    row?.focus?.();
  }

  return (
    <div class="tree-body" ref={body}>
      <For each={visible()}>{(r) => (
        <div
          class={'tree-row depth-' + Math.min(r.depth, 3)
            + (r.id === props.selected ? ' selected' : '')}
          data-id={r.id}
          role="button"
          tabindex="0"

          aria-expanded={r.hasChildren ? !isClosed(r.id) : undefined}
          onClick={() => props.onSelect(r.id)}

          onKeyDown={(e) => {
            if (e.key === 'Enter' || e.key === ' ') {
              e.preventDefault();
              props.onSelect(r.id);
            } else if (r.hasChildren
              && (e.key === 'ArrowRight' ? isClosed(r.id)
                : e.key === 'ArrowLeft' && !isClosed(r.id))) {
              e.preventDefault();
              toggle(r.id);
            }
          }}
        >
          <Show
            when={r.hasChildren}
            fallback={<span class="tree-toggle tree-leaf" aria-hidden="true" />}
          >
            <span
              class="tree-toggle"
              aria-hidden="true"
              onClick={(e) => { e.stopPropagation(); toggle(r.id); }}
            >{isClosed(r.id) ? '▸' : '▾'}</span>
          </Show>
          <span class="tree-label" title={r.label}>{r.label}</span>
          <Show when={r.badge}>{(b) => (
            <span class={'tree-badge ' + r.kind}>{b()}</span>
          )}</Show>
        </div>
      )}</For>
    </div>
  );
}
