import { Show } from 'solid-js';
import type { JSX } from 'solid-js';
import { loadStatus } from '../../stores/corpus.js';
import { opfsOn } from '../../stores/source-management.js';
import { exampleSearchString } from '../../model/default-corpus.js';
import { text } from '../../stores/view.js';
import { startFresh } from './edit-mode.jsx';
import { openSourcesPanel } from './sources.jsx';
import './starter.css';

function Action(props: {
  kind: string; label: string; body: string; off?: boolean; offReason?: string;
  act: () => void;
}): JSX.Element {
  return (
    <li class="starter-card">
      <button
        type="button"
        class="starter-action"
        data-action={props.kind}
        disabled={props.off || undefined}
        title={props.off ? props.offReason : undefined}
        onClick={() => { if (!props.off) props.act(); }}
      >{props.label}</button>
      <p class="starter-body muted">{props.body}</p>
    </li>
  );
}

// The landing of a bare load. Three EQUAL doors: making, looking and loading are
// the same size here, because the app cannot know which one the visitor wants.
export function Starter(): JSX.Element {
  return (
    <Show when={loadStatus() === 'empty'}>
      <section class="starter" aria-labelledby="starter-title">
        <h2 class="starter-title" id="starter-title">{text('start.title')}</h2>
        <p class="starter-lead muted">{text('start.lead')}</p>
        <ul class="starter-actions">
          <Action
            kind="edit"
            label={text('start.editTitle')}
            body={text('start.editBody')}
            off={!opfsOn()}
            offReason={text('src.opfsOff')}
            act={() => { void startFresh(); }}
          />
          <li class="starter-card">
            {/* A link and not a button: the examples are a ?src= load, and that
                stays a navigation the reader can open in a new tab. */}
            <a class="starter-action" data-action="examples" href={exampleSearchString()}>
              {text('src.examples')}
            </a>
            <p class="starter-body muted">{text('start.examplesBody')}</p>
          </li>
          <Action
            kind="open"
            label={text('start.openTitle')}
            body={text('start.openBody')}
            act={openSourcesPanel}
          />
        </ul>
      </section>
    </Show>
  );
}
